                Notes = "Weather delay — rerouted via Las Vegas"
            }
        );

        await db.SaveChangesAsync();
    }
}

using System.Security.Claims;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Data;

namespace ShipmentTracker.Api;

public static class ShipmentEndpoints
{
    public static void MapShipmentApi(this WebApplication app)
    {
        var group = app.MapGroup("/api/shipments").RequireAuthorization();

        // Dispatchers: get all shipments with optional status filter
        group.MapGet("/", async (
            [FromQuery] string? status,
            [FromQuery] string? search,
            ApplicationDbContext db,
            ClaimsPrincipal user) =>
        {
            var role = user.FindFirstValue("Role");

            IQueryable<Shipment> query = db.Shipments;

            // Customers only see their own shipments
            if (role != "Dispatcher")
            {
                var email = user.FindFirstValue(ClaimTypes.Email) ?? "";
                query = query.Where(s => s.CustomerEmail == email);
            }

            if (!string.IsNullOrEmpty(status) && Enum.TryParse<ShipmentStatus>(status, true, out var st))
                query = query.Where(s => s.Status == st);

            if (!string.IsNullOrEmpty(search))
                query = query.Where(s =>
                    s.TrackingNumber.Contains(search) ||
                    s.Destination.Contains(search) ||
                    s.RecipientName.Contains(search));

            var shipments = await query.OrderByDescending(s => s.ShippedDate).ToListAsync();
            return Results.Ok(shipments);
        });

        // Get a single shipment
        group.MapGet("/{id:int}", async (int id, ApplicationDbContext db, ClaimsPrincipal user) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            var role = user.FindFirstValue("Role");
            if (role != "Dispatcher")
            {
                var email = user.FindFirstValue(ClaimTypes.Email) ?? "";
                if (shipment.CustomerEmail != email) return Results.Forbid();
            }

            return Results.Ok(shipment);
        });

        // Track by tracking number (public-ish — still requires auth)
        group.MapGet("/track/{trackingNumber}", async (
            string trackingNumber,
            ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments
                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
        });

        // Dispatcher: update shipment status
        group.MapPut("/{id:int}/status", async (
            int id,
