@page "/shipments"
@rendermode InteractiveAuto
@attribute [Microsoft.AspNetCore.Authorization.Authorize]

@using ShipmentTracker.Client.Models
@inject HttpClient Http

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>📦 Shipment Dashboard</h1>

<div class="row mb-3">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Search tracking #, destination, recipient…"
               @bind="searchTerm" @bind:event="oninput" @onkeyup="HandleSearch" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @onchange="OnStatusFilterChanged">
            <option value="">All statuses</option>
            @foreach (var s in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@s">@s</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <button class="btn btn-success" @onclick="ToggleNewForm">
            @(showNewForm ? "Cancel" : "+ New Shipment")
        </button>
    </div>
</div>

@if (showNewForm)
{
    <div class="card mb-4 p-3">
        <h5>Create New Shipment</h5>
        <div class="row g-2">
            <div class="col-md-3">
                <input class="form-control" placeholder="Tracking #" @bind="newShipment.TrackingNumber" />
            </div>
            <div class="col-md-3">
                <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
            </div>
            <div class="col-md-3">
                <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
            </div>
            <div class="col-md-3">
                <input class="form-control" placeholder="Recipient Name" @bind="newShipment.RecipientName" />
            </div>
            <div class="col-md-3">
                <input class="form-control" placeholder="Customer Email" @bind="newShipment.CustomerEmail" />
            </div>
            <div class="col-md-3">
                <label class="form-label">Est. Delivery</label>
                <input type="date" class="form-control" @bind="newShipment.EstimatedDelivery" />
            </div>
            <div class="col-md-3">
                <input class="form-control" placeholder="Notes (optional)" @bind="newShipment.Notes" />
            </div>
            <div class="col-md-3 d-flex align-items-end">
                <button class="btn btn-primary" @onclick="CreateShipment" disabled="@isCreating">
                    @(isCreating ? "Creating…" : "Create")
                </button>
            </div>
        </div>
        @if (!string.IsNullOrEmpty(createError))
        {
            <div class="alert alert-danger mt-2">@createError</div>
        }
    </div>
}

@if (shipments == null)
{
    <p><em>Loading shipments…</em></p>
}
else if (shipments.Length == 0)
{
    <p>No shipments found.</p>
}
else
{
    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Shipped</th>
                <th>Est. Delivery</th>
                <th>Recipient</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var s in shipments)
            {
                <tr>
                    <td><strong>@s.TrackingNumber</strong></td>
                    <td>@s.Origin</td>
                    <td>@s.Destination</td>
                    <td>
                        <span class="badge @StatusBadgeClass(s.Status)">@s.Status</span>
                    </td>
                    <td>@s.ShippedDate.ToString("MMM dd, yyyy")</td>
                    <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                    <td>@s.RecipientName</td>
                    <td>
                        @if (editingId == s.Id)
                        {
                            <select class="form-select form-select-sm d-inline-block w-auto"
                                    @onchange="e => UpdateStatus(s.Id, e.Value?.ToString())">
                                @foreach (var st in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@st" selected="@(st == s.Status)">@st</option>
                                }
                            </select>
                            <button class="btn btn-sm btn-outline-secondary ms-1" @onclick="() => editingId = null">
                                ✕
                            </button>
                        }
                        else
                        {
                            <button class="btn btn-sm btn-outline-primary" @onclick="() => editingId = s.Id">
                                Update Status
                            </button>
                        }
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private ShipmentDto[]? shipments;
    private string searchTerm = "";
    private string statusFilter = "";
    private int? editingId;
    private bool showNewForm;
    private bool isCreating;
    private string? createError;
    private CreateShipmentModel newShipment = new();

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        var url = "/api/shipments?";
        if (!string.IsNullOrEmpty(statusFilter))
            url += $"status={Uri.EscapeDataString(statusFilter)}&";
        if (!string.IsNullOrEmpty(searchTerm))
            url += $"search={Uri.EscapeDataString(searchTerm)}&";

        shipments = await Http.GetFromJsonAsync<ShipmentDto[]>(url.TrimEnd('&', '?'));
    }

    private async Task HandleSearch()
    {
        await LoadShipments();
    }

    private async Task OnStatusFilterChanged(ChangeEventArgs e)
    {
        statusFilter = e.Value?.ToString() ?? "";
        await LoadShipments();
    }

    private async Task UpdateStatus(int id, string? newStatus)
    {
        if (string.IsNullOrEmpty(newStatus)) return;

        var response = await Http.PutAsJsonAsync($"/api/shipments/{id}/status",
            new { Status = newStatus, Notes = (string?)null });
        if (response.IsSuccessStatusCode)
        {
            editingId = null;
            await LoadShipments();
        }
    }

    private async Task CreateShipment()
    {
        isCreating = true;
        createError = null;

        var response = await Http.PostAsJsonAsync("/api/shipments", newShipment);
        if (response.IsSuccessStatusCode)
        {
            showNewForm = false;
            newShipment = new();
            await LoadShipments();
        }
        else
        {
            createError = $"Failed to create shipment: {response.StatusCode}";
        }

        isCreating = false;
    }

    private void ToggleNewForm() => showNewForm = !showNewForm;

    private static string StatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.Delayed => "bg-warning text-dark",
        ShipmentStatus.Returned => "bg-danger",
        _ => "bg-secondary"
    };

    private class CreateShipmentModel
    {
        public string TrackingNumber { get; set; } = "";
        public string Origin { get; set; } = "";
        public string Destination { get; set; } = "";
        public string RecipientName { get; set; } = "";
        public string CustomerEmail { get; set; } = "";
        public DateTime EstimatedDelivery { get; set; } = DateTime.UtcNow.AddDays(5);
        public string? Notes { get; set; }
    }
}

