{"file_text": "@page "/tracking"
@rendermode InteractiveAuto
@attribute [Microsoft.AspNetCore.Authorization.Authorize]

@using ShipmentTracker.Client.Models
@inject HttpClient Http

<PageTitle>Track My Shipments</PageTitle>

<h1>📍 Track Your Shipments</h1>

<div class="row mb-4">
    <div class="col-md-5">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g. TRK-20260001)"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isSearching">
                @(isSearching ? "Searching…" : "Track")
            </button>
        </div>
    </div>
</div>

@if (searchPerformed && trackedShipment is null && !isSearching)
{
    <div class="alert alert-warning">
        No shipment found with tracking number <strong>@lastSearched</strong>. Please check the number and try again.
    </div>
}

@if (trackedShipment is not null)
{
    <div class="card mb-4">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">@trackedShipment.TrackingNumber</h5>
            <span class="badge @StatusBadgeClass(trackedShipment.Status) fs-6">@trackedShipment.Status</span>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>From</dt>
                        <dd>@trackedShipment.Origin</dd>
                        <dt>To</dt>
                        <dd>@trackedShipment.Destination</dd>
                        <dt>Recipient</dt>
                        <dd>@trackedShipment.RecipientName</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Shipped Date</dt>
                        <dd>@trackedShipment.ShippedDate.ToString("MMMM dd, yyyy")</dd>
                        <dt>Estimated Delivery</dt>
                        <dd>
                            <strong>@trackedShipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</strong>
                            @if (trackedShipment.Status != ShipmentStatus.Delivered)
                            {
                                var daysLeft = (trackedShipment.EstimatedDelivery - DateTime.UtcNow).Days;
                                <span class="text-muted ms-2">
                                    (@(daysLeft > 0 ? $"in {daysLeft} day(s)" : daysLeft == 0 ? "today" : $"{Math.Abs(daysLeft)} day(s) overdue"))
                                </span>
                            }
                        </dd>
                        @if (trackedShipment.ActualDelivery.HasValue)
                        {
                            <dt>Delivered On</dt>
                            <dd class="text-success">
                                ✅ @trackedShipment.ActualDelivery.Value.ToString("MMMM dd, yyyy")
                            </dd>
                        }
                    </dl>
                </div>
            </div>

            @if (!string.IsNullOrEmpty(trackedShipment.Notes))
            {
                <div class="alert alert-info mt-2">
                    <strong>Notes:</strong> @trackedShipment.Notes
                </div>
            }

            <!-- Visual status timeline -->
            <h6 class="mt-4">Shipment Progress</h6>
            <div class="d-flex justify-content-between position-relative mt-3 mb-2">
                @{
                    var stages = new[] {
                        ShipmentStatus.Pending,
                        ShipmentStatus.PickedUp,
                        ShipmentStatus.InTransit,
                        ShipmentStatus.OutForDelivery,
                        ShipmentStatus.Delivered
                    };
                    var currentIdx = Array.IndexOf(stages, trackedShipment.Status);
                    if (trackedShipment.Status == ShipmentStatus.Delayed)
                        currentIdx = Array.IndexOf(stages, ShipmentStatus.InTransit);
                }
                @for (int i = 0; i < stages.Length; i++)
                {
                    var isActive = i <= currentIdx;
                    var isCurrent = stages[i] == trackedShipment.Status ||
                                    (trackedShipment.Status == ShipmentStatus.Delayed && stages[i] == ShipmentStatus.InTransit);
                    <div class="text-center flex-fill">
                        <div class="rounded-circle d-inline-flex align-items-center justify-content-center"
                             style="width:36px;height:36px;background:@(isActive ? "#0d6efd" : "#dee2e6");color:@(isActive ? "white" : "#6c757d")">
                            @(i + 1)
                        </div>
                        <div class="small mt-1 @(isCurrent ? "fw-bold" : "")">
                            @(trackedShipment.Status == ShipmentStatus.Delayed && stages[i] == ShipmentStatus.InTransit
                                ? "Delayed" : stages[i].ToString())
                        </div>
                    </div>
                }
            </div>
        </div>
    </div>
}

<hr />
<h4>Your Shipments</h4>

@if (myShipments == null)
{
    <p><em>Loading your shipments…</em></p>
}
else if (myShipments.Length == 0)
{
    <p class="text-muted">You have no shipments on file. Use the tracking number search above to look up a shipment.</p>
}
else
{
    <div class="row">
        @foreach (var s in myShipments)
        {
            <div class="col-md-6 col-lg-4 mb-3">
                <div class="card h-100 @(s.Status == ShipmentStatus.Delayed ? "border-warning" : "")">
                    <div class="card-body">
                        <h6 class="card-title">
                            @s.TrackingNumber
                            <span class="badge @StatusBadgeClass(s.Status) ms-2">@s.Status</span>
                        </h6>
                        <p class="card-text mb-1">
                            <small class="text-muted">@s.Origin → @s.Destination</small>
                        </p>
                        <p class="card-text mb-1">
                            Est. delivery: <strong>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</strong>
                        </p>
                        @if (s.ActualDelivery.HasValue)
                        {
                            <p class="text-success mb-0">
                                ✅ Delivered @s.ActualDelivery.Value.ToString("MMM dd, yyyy")
                            </p>
                        }
                    </div>
                    <div class="card-footer">
                        <button class="btn btn-sm btn-outline-primary" @onclick="() => TrackById(s.TrackingNumber)">
                            View Details
                        </button>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private ShipmentDto[]? myShipments;
    private ShipmentDto? trackedShipment;
    private string trackingNumber = "";
    private string lastSearched = "";
    private bool searchPerformed;
    private bool isSearching;

    protected override async Task OnInitializedAsync()
    {
        myShipments = await Http.GetFromJsonAsync<ShipmentDto[]>("/api/shipments");
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isSearching = true;
        searchPerformed = true;
        lastSearched = trackingNumber.Trim();

        var response = await Http.GetAsync($"/api/shipments/track/{Uri.EscapeDataString(lastSearched)}");
        trackedShipment = response.IsSuccessStatusCode
            ? await response.Content.ReadFromJsonAsync<ShipmentDto>()
            : null;

        isSearching = false;
    }

    private async Task TrackById(string tn)
    {
        trackingNumber = tn;
        await TrackShipment();
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private static string StatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.Delayed => "bg-warning text-dark",
        ShipmentStatus.Returned => "bg-danger",
        _ => "bg-secondary"
    };
}
